import app from 'flarum/forum/app';
import Modal from 'flarum/common/components/Modal';
import Button from 'flarum/common/components/Button';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { api, t } from '../util';
/**
 * The last step: a number, then a button. An email cannot be recalled, so the
 * confirmation says exactly how many people it is about to reach.
 */
export default class SendModal extends Modal {
  counts = null;
  sending = false;
  oninit(vnode) {
    super.oninit(vnode);
    api('POST', '/count', {
      filters: this.attrs.filters
    }).then(counts => {
      this.counts = counts;
      m.redraw();
    });
  }
  className() {
    return 'HeraldSendModal Modal--small';
  }
  title() {
    return this.attrs.resend ? t('send.resend_title') : t('send.title');
  }
  content() {
    const counts = this.counts;
    return m("div", {
      className: "Modal-body"
    }, !counts ? m(LoadingIndicator, null) : m("div", {
      className: "Form Form--centered"
    }, m("p", {
      className: "HeraldSend-reach"
    }, t('send.reach', {
      count: counts.reach,
      formatted: counts.reach.toLocaleString(app.data.locale)
    })), m("p", {
      className: "HeraldSend-subject"
    }, "\u201C", this.attrs.subject, "\u201D"), counts.optedOut || counts.unconfirmed ? m("p", {
      className: "helpText"
    }, t('send.excluded', {
      optedOut: counts.optedOut.toLocaleString(app.data.locale),
      unconfirmed: counts.unconfirmed.toLocaleString(app.data.locale)
    })) : null, m("p", {
      className: "helpText"
    }, t('send.cannot_recall')), m("div", {
      className: "Form-group"
    }, m(Button, {
      className: "Button Button--primary Button--block",
      icon: "fas fa-paper-plane",
      loading: this.sending,
      disabled: counts.reach === 0,
      onclick: () => this.send()
    }, counts.reach === 0 ? t('send.nobody') : t('send.confirm', {
      count: counts.reach
    })))));
  }
  send() {
    this.sending = true;
    api('POST', `/mailings/${this.attrs.mailingId}/send`).then(response => {
      this.hide();
      this.attrs.onsend(response);
    }).catch(() => {
      this.sending = false;
      m.redraw();
    });
  }
}
flarum.reg.add('ernestdefoe-herald', 'forum/components/SendModal', SendModal);